# 读取 zh 键集合（作为全集校验）
zh_keys = []
for f in ZH_FILES:
    text = io.open(f, encoding='utf-8').read()
    zh_keys += re.findall(r'<data name="([^"]+)"', text)
zh_set = set(zh_keys)

table_keys = {row[0] for row in T}
missing_in_table = zh_set - table_keys
extra_in_table = table_keys - zh_set
if missing_in_table:
    raise SystemExit('表缺键: ' + ', '.join(sorted(missing_in_table)))
if extra_in_table:
    raise SystemExit('表多键: ' + ', '.join(sorted(extra_in_table)))

LANGS = [('ja', 1), ('ko', 2), ('de', 3), ('fr', 4), ('es', 5)]
for lang, idx in LANGS:
    directory = os.path.join(ROOT, lang)
    os.makedirs(directory, exist_ok=True)
    out = list(HEADER)
    for row in T:
        out.append(f'  <data name="{row[0]}" xml:space="preserve"><value>{esc(row[idx])}</value></data>')
    out.append('</root>\n')
    io.open(os.path.join(directory, 'Resources.resw'), 'w', encoding='utf-8', newline='').write('\n'.join(out))
    print(lang, 'keys =', len(T))

# zh-CN / en-US 由人工维护（此处仅生成 ja/ko/de/fr/es）
print('done')
